import{_ as l,o as e,c as i,ae as r}from"./chunks/framework.RRduUuAx.js";const c=JSON.parse('{"title":"複数帳本（マルチ Ledger）","description":"","frontmatter":{},"headers":[],"relativePath":"v1/ja/guide/04-multi-ledger-guide.md","filePath":"v1/ja/guide/04-multi-ledger-guide.md"}'),o={name:"v1/ja/guide/04-multi-ledger-guide.md"};function t(n,a,h,s,d,u){return e(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="複数帳本-マルチ-ledger" tabindex="-1">複数帳本（マルチ Ledger） <a class="header-anchor" href="#複数帳本-マルチ-ledger" aria-label="Permalink to &quot;複数帳本（マルチ Ledger）&quot;">​</a></h1><h2 id="📋-概要" tabindex="-1">📋 概要 <a class="header-anchor" href="#📋-概要" aria-label="Permalink to &quot;📋 概要&quot;">​</a></h2><p>Koala は複数の帳本（Ledger）を作成でき、用途ごとに明細・カテゴリ・統計を分けて管理できます。例えば以下のような使い分けに向いています。</p><ul><li>個人用</li><li>家計用</li><li>旅行用</li><li>ベビー用</li><li>車関連</li><li>リフォーム</li><li>ビジネス用</li></ul><hr><h2 id="🚀-クイックスタート" tabindex="-1">🚀 クイックスタート <a class="header-anchor" href="#🚀-クイックスタート" aria-label="Permalink to &quot;🚀 クイックスタート&quot;">​</a></h2><h3 id="新しい帳本を作成" tabindex="-1">新しい帳本を作成 <a class="header-anchor" href="#新しい帳本を作成" aria-label="Permalink to &quot;新しい帳本を作成&quot;">​</a></h3><ol><li>Koala を開く</li><li><strong>設定</strong> → <strong>帳本管理</strong></li><li>右上の <strong>+</strong> をタップ</li><li>帳本情報を入力（名称、説明、アイコン、通貨など）</li><li><strong>保存</strong></li></ol><h3 id="帳本を切り替える" tabindex="-1">帳本を切り替える <a class="header-anchor" href="#帳本を切り替える" aria-label="Permalink to &quot;帳本を切り替える&quot;">​</a></h3><ol><li><strong>設定</strong> → <strong>帳本管理</strong></li><li>一覧から切り替えたい帳本カードをタップ</li></ol><blockquote><p>📝 注意：切り替え後は、概覧・統計・明細一覧などの表示が「現在の帳本」のデータになります。</p></blockquote><hr><h2 id="📚-帳本の管理" tabindex="-1">📚 帳本の管理 <a class="header-anchor" href="#📚-帳本の管理" aria-label="Permalink to &quot;📚 帳本の管理&quot;">​</a></h2><h3 id="帳本を編集" tabindex="-1">帳本を編集 <a class="header-anchor" href="#帳本を編集" aria-label="Permalink to &quot;帳本を編集&quot;">​</a></h3><ol><li><strong>帳本管理</strong> を開く</li><li>対象帳本の <strong>…（その他）</strong> をタップ</li><li>帳本詳細で、名称/説明/アイコン/通貨などを編集</li><li><strong>保存</strong></li></ol><h3 id="帳本を削除" tabindex="-1">帳本を削除 <a class="header-anchor" href="#帳本を削除" aria-label="Permalink to &quot;帳本を削除&quot;">​</a></h3><ol><li>帳本詳細を開く</li><li><strong>帳本を削除</strong> をタップ</li><li>確認して削除</li></ol><blockquote><p>⚠️ 注意：</p><ul><li>削除すると、その帳本と帳本内の明細はこの端末から削除されます。</li><li>クラウド同期を利用している場合は、次回同期でクラウド側にも反映されます。</li><li>アプリ内で復元することはできません。</li></ul></blockquote><hr><h2 id="💰-帳本の通貨-本位通貨" tabindex="-1">💰 帳本の通貨（本位通貨） <a class="header-anchor" href="#💰-帳本の通貨-本位通貨" aria-label="Permalink to &quot;💰 帳本の通貨（本位通貨）&quot;">​</a></h2><ul><li>帳本ごとに通貨を設定できます。</li><li>通貨を変更すると、表示や集計の見え方が変わる場合があります。</li></ul><blockquote><p>💡 ヒント：通貨について詳しくは <a href="./05-exchange-rate-guide">為替説明</a> を参照してください。</p></blockquote><hr><h2 id="📊-データの分離" tabindex="-1">📊 データの分離 <a class="header-anchor" href="#📊-データの分離" aria-label="Permalink to &quot;📊 データの分離&quot;">​</a></h2><ul><li><strong>明細</strong>：帳本ごとに独立</li><li><strong>カテゴリ</strong>：帳本ごとに独立</li><li><strong>タグ</strong>：帳本ごとに独立</li><li><strong>統計</strong>：帳本ごとに独立</li></ul><blockquote><p>📝 注意：<strong>口座（アカウント）は端末共通</strong>のため、複数帳本で同じ口座を使用できます。</p></blockquote><hr><h2 id="🔄-同期-クラウド" tabindex="-1">🔄 同期（クラウド） <a class="header-anchor" href="#🔄-同期-クラウド" aria-label="Permalink to &quot;🔄 同期（クラウド）&quot;">​</a></h2><p>クラウド同期を利用している場合、帳本も同期対象です。</p><ul><li>アプリ起動時</li><li>手動同期</li><li>帳本の作成/編集/削除後 など</li></ul><hr><h2 id="🔧-よくある質問" tabindex="-1">🔧 よくある質問 <a class="header-anchor" href="#🔧-よくある質問" aria-label="Permalink to &quot;🔧 よくある質問&quot;">​</a></h2><h3 id="q1-帳本はいくつまで作れますか" tabindex="-1">Q1：帳本はいくつまで作れますか？ <a class="header-anchor" href="#q1-帳本はいくつまで作れますか" aria-label="Permalink to &quot;Q1：帳本はいくつまで作れますか？&quot;">​</a></h3><p>最大 <strong>50</strong> 個まで作成できます。</p><h3 id="q2-口座は帳本ごとですか" tabindex="-1">Q2：口座は帳本ごとですか？ <a class="header-anchor" href="#q2-口座は帳本ごとですか" aria-label="Permalink to &quot;Q2：口座は帳本ごとですか？&quot;">​</a></h3><p>いいえ。口座は端末共通で、すべての帳本で共有されます。</p><hr><p><strong>最終更新</strong>：2026 年 1 月</p>',38)])])}const q=l(o,[["render",t]]);export{c as __pageData,q as default};
